mapper.select:
SELECT f.id AS id, u.id AS user_id, u.nickname, u.avatar_url AS avatar_url,
EXISTS (SELECT 1 FROM follows v WHERE v.follower_id = #{viewerId} AND v.following_id = u.id)
FALSE AS following FROM follows f INNER JOIN users u ON u.id = f.follower_id AND u.status = 1 WHERE f.following_id = #{userId} AND f.id < #{cursor} ORDER BY f.id DESC LIMIT #{limit}

